//
// Road bike model (GLB generated by tools/blender/argus_bike/build_bike.py).
//
// The GLB is parsed once per scene (ModelCache) and instantiated for every rider (ghosts
// get cloned, translucent materials). The GLB exposes animatable nodes:
//   wheel_rear / wheel_front   spin with the speed (rolling radius from the metadata)
//   crank, pedal_L/R           crank angle from the cadence; pedals stay level
//   pulley_upper/lower         jockey wheels, driven by the chain speed
//   chain_outer/inner          link templates drawn as thin instances along the chain path
//   steer                      steering about the head-tube axis
//   socket_*                   rider contact points (saddle, hoods, drops, pedals)
//
// Rotation senses are calibrated at load time against the model itself, so they do not
// depend on how the glTF handedness conversion orients the nodes.
//
// Local space of the parent (the rider body): +z forward, +y up, +x right, origin on the
// road between the wheels.

import { Vector3, Matrix, Quaternion, Color3 } from './babylon.js';
import { instantiate } from './ModelCache.js';
import bikeUrl from '../../assets/scene3d/models/argus_bike.glb?url';

const X_AXIS = new Vector3(1, 0, 0);

export class BikeModel {
    /**
     * @param {Scene} scene
     * @param {TransformNode} parent node in rider-body space
     * @param {{name?: string, alpha?: number}} opts alpha < 1 → translucent ghost
     * @returns {Promise<BikeModel>}
     */
    static async create(scene, parent, { name = 'bike', alpha = 1 } = {}) {
        const entries = await instantiate(scene, bikeUrl, name, alpha < 1);
        return new BikeModel(scene, parent, entries, { name, alpha });
    }

    constructor(scene, parent, entries, { name, alpha }) {
        this.scene = scene;
        this.name = name;
        this.root = entries.rootNodes[0];
        this.root.parent = parent;
        this.parent = parent;
        const all = this.root.getDescendants(false);
        const find = (n) => {
            const node = all.find((d) => d.name === `${name}:${n}`);
            if (!node) throw new Error(`bike model: node "${n}" missing`);
            return node;
        };
        const bikeNode = find('argus_bike');
        const extras = bikeNode.metadata?.gltf?.extras?.argus_bike;
        if (!extras) throw new Error('bike model: metadata missing');
        this.meta = typeof extras === 'string' ? JSON.parse(extras) : extras;
        this.nodes = {
            wheelRear: find('wheel_rear'), wheelFront: find('wheel_front'), crank: find('crank'),
            pedalL: find('pedal_L'), pedalR: find('pedal_R'), steer: find('steer'),
            pulleyUpper: find('pulley_upper'), pulleyLower: find('pulley_lower')
        };
        for (const n of Object.values(this.nodes)) n.rotationQuaternion = n.rotationQuaternion || new Quaternion();
        this._base = new Map(Object.values(this.nodes).map((n) => [n, n.rotationQuaternion.clone()]));
        this.meshes = this.root.getChildMeshes(false).filter((m) => m.getTotalVertices() > 0);
        for (const m of this.meshes) {
            m.isPickable = false;
            m.receiveShadows = true;
        }
        if (alpha < 1) this._makeGhost(alpha);
        this._sockets = {
            saddle: find('socket_saddle'), hoodL: find('socket_hood_L'), hoodR: find('socket_hood_R'),
            dropL: find('socket_drop_L'), dropR: find('socket_drop_R'), pedalL: find('socket_pedal_L'), pedalR: find('socket_pedal_R')
        };
        this._chain = this._setupChain(find('chain_outer_mesh'), find('chain_inner_mesh'));
        this._steerAxis = Vector3.FromArray(this.meta.steerAxis).normalize();
        this._q = new Quaternion();
        this._tmpM = new Matrix();
        this.wheelAngle = 0;
        this.crankAngle = 0;
        this.steerAngle = 0;
        this._calibrate();
        this.fit = this._measureFit();
        this.setPose(0, 0, 0);
    }

    // ------------------------------------------------------------------

    _makeGhost(alpha) {
        const seen = new Set();
        for (const m of this.meshes) {
            const mat = m.material;
            if (!mat || seen.has(mat)) continue;
            seen.add(mat);
            mat.alpha = alpha;
            mat.transparencyMode = 2; // ALPHABLEND
            if (mat.emissiveColor) mat.emissiveColor = new Color3(0.0, 0.35, 0.45);
        }
    }

    _setupChain(outer, inner) {
        const path = this.meta.chainPath.map((p) => Vector3.FromArray(p));
        const n = path.length;
        const cum = new Float32Array(n + 1);
        for (let i = 0; i < n; i++) cum[i + 1] = cum[i] + Vector3.Distance(path[i], path[(i + 1) % n]);
        const total = cum[n];
        const pitch = this.meta.chainPitch;
        const links = Math.round(total / pitch);
        const chain = { path, cum, total, pitch, links, meshes: [outer, inner], buffers: [], half: links / 2, _p: new Vector3(), _q: new Vector3() };
        for (const m of chain.meshes) {
            const buf = new Float32Array(16 * chain.half);
            m.thinInstanceSetBuffer('matrix', buf, 16, false);
            m.alwaysSelectAsActiveMesh = true; // bounds of the moving instances
            chain.buffers.push(buf);
        }
        return chain;
    }

    _chainPoint(s, out) {
        const c = this._chain;
        s = ((s % c.total) + c.total) % c.total;
        // Binary search on the cumulative lengths.
        let lo = 0, hi = c.path.length - 1;
        while (lo < hi) {
            const mid = (lo + hi + 1) >> 1;
            if (c.cum[mid] <= s) lo = mid; else hi = mid - 1;
        }
        const a = c.path[lo], b = c.path[(lo + 1) % c.path.length];
        const t = (s - c.cum[lo]) / Math.max(1e-9, c.cum[lo + 1] - c.cum[lo]);
        return Vector3.LerpToRef(a, b, t, out);
    }

    _updateChain(travel) {
        const c = this._chain;
        const a = c._p, b = c._q;
        const fwd = new Vector3(), up = new Vector3();
        for (let i = 0; i < c.links; i++) {
            this._chainPoint(travel + i * c.pitch, a);
            this._chainPoint(travel + (i + 1) * c.pitch, b);
            // Template: forward = -Z, lateral = +X (glTF space of the GLB nodes).
            b.subtractToRef(a, fwd).normalize();
            // Z axis image = -fwd; Y = Z × X.
            const zx = -fwd.x, zy = -fwd.y, zz = -fwd.z;
            Vector3.CrossToRef(new Vector3(zx, zy, zz), X_AXIS, up);
            const buf = c.buffers[i & 1];
            const o = (i >> 1) * 16;
            buf[o] = 1; buf[o + 1] = 0; buf[o + 2] = 0; buf[o + 3] = 0;
            buf[o + 4] = up.x; buf[o + 5] = up.y; buf[o + 6] = up.z; buf[o + 7] = 0;
            buf[o + 8] = zx; buf[o + 9] = zy; buf[o + 10] = zz; buf[o + 11] = 0;
            buf[o + 12] = (a.x + b.x) / 2; buf[o + 13] = (a.y + b.y) / 2; buf[o + 14] = (a.z + b.z) / 2; buf[o + 15] = 1;
        }
        for (const m of c.meshes) m.thinInstanceBufferUpdated('matrix');
    }

    /** Position of a node in parent (rider body) space, after forcing the transforms. */
    _local(node, out = new Vector3()) {
        const chain = [];
        for (let n = node; n && n !== this.parent; n = n.parent) chain.push(n);
        for (let i = chain.length - 1; i >= 0; i--) chain[i].computeWorldMatrix(true);
        this.parent.computeWorldMatrix(true);
        this.parent.getWorldMatrix().invertToRef(this._tmpM);
        return Vector3.TransformCoordinatesToRef(node.getAbsolutePosition(), this._tmpM, out);
    }

    _rotate(node, axis, angle) {
        Quaternion.RotationAxisToRef(axis, angle, this._q);
        this._base.get(node).multiplyToRef(this._q, node.rotationQuaternion);
    }

    /** Signs so that +angle = forward rolling / pedalling and +steer = turning right. */
    _calibrate() {
        this.crankSign = 1;
        this.steerSign = 1;
        const p0 = this._local(this._sockets.pedalR).clone();
        this._rotate(this.nodes.crank, X_AXIS, 0.3);
        const p1 = this._local(this._sockets.pedalR).clone();
        // The right pedal starts forward (+z); pedalling forward moves it down.
        this.crankSign = p1.y < p0.y ? 1 : -1;
        this._rotate(this.nodes.crank, X_AXIS, 0);
        const h0 = this._local(this._sockets.hoodR).clone();
        this._rotate(this.nodes.steer, this._steerAxis, 0.2);
        const h1 = this._local(this._sockets.hoodR).clone();
        // Turning right swings the right hood backwards.
        this.steerSign = h1.z < h0.z ? 1 : -1;
        this._rotate(this.nodes.steer, this._steerAxis, 0);
    }

    _measureFit() {
        const s = this._sockets;
        return {
            saddle: this._local(s.saddle).clone(),
            hands: [this._local(s.hoodL).clone(), this._local(s.hoodR).clone()],
            drops: [this._local(s.dropL).clone(), this._local(s.dropR).clone()],
            bb: this._local(this.nodes.crank).clone(),
            crankLength: this.meta.crankLength,
            wheelRadius: this.meta.wheelRadius,
            wheelbase: this.meta.wheelbase
        };
    }

    /** Ball-of-foot contact on the pedal (`side` -1 left / +1 right), current pose. */
    pedalContact(side, out = new Vector3()) {
        return this._local(side > 0 ? this._sockets.pedalR : this._sockets.pedalL, out);
    }

    /**
     * @param {number} crank radians, 0 = right crank forward, increasing while pedalling
     * @param {number} wheel radians of wheel rotation
     * @param {number} steer radians, + = right
     */
    setPose(crank, wheel, steer) {
        this.crankAngle = crank;
        this.wheelAngle = wheel;
        this.steerAngle = steer;
        const n = this.nodes, cs = this.crankSign;
        this._rotate(n.crank, X_AXIS, cs * crank);
        // Pedals counter-rotate (relative to the crank) and stay level.
        this._rotate(n.pedalR, X_AXIS, -cs * crank);
        this._rotate(n.pedalL, X_AXIS, -cs * crank);
        this._rotate(n.wheelRear, X_AXIS, cs * wheel);
        this._rotate(n.wheelFront, X_AXIS, cs * wheel);
        this._rotate(n.steer, this._steerAxis, this.steerSign * steer);
        // Chain speed = big-ring pitch radius × crank angle; jockeys turn with it.
        const ringR = this.meta.chainPitch / (2 * Math.sin(Math.PI / this.meta.chainringTeeth));
        const pulleyR = this.meta.chainPitch / (2 * Math.sin(Math.PI / this.meta.pulleyTeeth));
        const travel = crank * ringR;
        this._rotate(n.pulleyLower, X_AXIS, cs * travel / pulleyR);
        this._rotate(n.pulleyUpper, X_AXIS, -cs * travel / pulleyR);
        this._updateChain(travel);
    }

    setEnabled(on) {
        this.root.setEnabled(on);
    }

    dispose() {
        this.root.dispose(false, true);
    }
}
